        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool SaveFile(string file, void* data, ulong datasize)
        {
            nint p_file = 0;
            try
            {
                p_file = file is null ? 0 : Marshal.StringToCoTaskMemUTF8(file);
                byte ret = SaveFileNative((byte*)p_file, data, datasize);
                return ret != 0;
            }
            finally
            {
                if (p_file != 0)
                    Marshal.FreeCoTaskMem(p_file);
            }
        }

