        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool LoadWAV(string path, SDLAudioSpecPtr spec, byte** audioBuf, ref uint audioLen)
        {
            nint p_path = 0;
            try
            {
                p_path = path is null ? 0 : Marshal.StringToCoTaskMemUTF8(path);
                fixed (uint* p_audioLen = &audioLen)
                {
                    byte ret = LoadWAVNative((byte*)p_path, (SDLAudioSpec*)spec.Handle, audioBuf, (uint*)p_audioLen);
                    return ret != 0;
                }
            }
            finally
            {
                if (p_path != 0)
                    Marshal.FreeCoTaskMem(p_path);
            }
        }

