        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool SaveBMP(SDLSurfacePtr surface, string file)
        {
            nint p_file = 0;
            try
            {
                p_file = file is null ? 0 : Marshal.StringToCoTaskMemUTF8(file);
                byte ret = SaveBMPNative((SDLSurface*)surface.Handle, (byte*)p_file);
                return ret != 0;
